body { margin: 0; }

.app {
  display: grid;
  grid-template-columns: 220px 1fr;
  min-height: 100vh;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 16px 12px;
  background: #16324f;
}

.sidebar-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  border: 0;
  border-radius: 8px;
  padding: 10px 12px;
  color: #d7e4f2;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

